<?php declare(strict_types=1); namespace Annam; $title='Enter a booking';$subtitle='Enter the customer phone number, select the food, then review the order.';$actions='<a class="o-btn" href="/billing/">Back to billing</a>';
function billing_line(string $index,array $catalog,array $values):void { $prefix='lines-'.$index.'-'; ?>
<div class="b-line" data-line><div class="b-line-item"><label class="b-label" for="id_<?= e($prefix) ?>item">Item</label><select class="o-input" name="<?= e($prefix) ?>item" id="id_<?= e($prefix) ?>item" required><option value="">Select an item</option><?php foreach($catalog as $item): ?><option value="<?= e($item['id']) ?>" <?= (string)($values[$prefix.'item']??'')===(string)$item['id']?'selected':'' ?>><?= e($item['name'].' — ₹'.$item['price']) ?></option><?php endforeach; ?></select><input type="hidden" name="<?= e($prefix) ?>meal" value="<?= e($values[$prefix.'meal']??'') ?>"></div><div class="b-line-qty"><label class="b-label" for="id_<?= e($prefix) ?>quantity">Quantity</label><div class="b-stepper"><button type="button" data-step="-1" aria-label="Decrease quantity">−</button><input class="o-input" type="number" id="id_<?= e($prefix) ?>quantity" name="<?= e($prefix) ?>quantity" value="<?= e($values[$prefix.'quantity']??1) ?>" min="1" max="999" required><button type="button" data-step="1" aria-label="Increase quantity">+</button></div></div><div class="b-line-price"><span class="b-label">Amount</span><strong data-line-total>—</strong></div><label class="b-remove"><input type="checkbox" name="<?= e($prefix) ?>DELETE" value="1" <?= !empty($values[$prefix.'DELETE'])?'checked':'' ?>>Remove</label></div>
<?php } ?>
<form method="post" class="b-booking" id="booking-form" data-customer-lookup="/billing/customer-lookup/" data-lookup-initial="true"><?= csrf() ?><input type="hidden" name="token" value="<?= e($token) ?>"><?php if($error): ?><div class="o-flash o-flash-error" role="alert"><?= e($error) ?></div><?php endif; ?><div class="b-booking-main"><section class="o-card b-panel"><div class="b-panel-head"><span class="b-step-number">1</span><div><h2>Customer &amp; booking</h2><p>Who is this order for?</p></div></div><div class="o-grid-form">
<?php foreach(['phone'=>"Customer phone",'name'=>'Customer name'] as $key=>$label): ?><label class="o-field"><?= e($label) ?><input class="o-input" name="<?= e($key) ?>" id="id_<?= e($key) ?>" type="<?= $key==='delivery_date'?'date':($key==='phone'?'tel':'text') ?>" value="<?= e($values[$key]??(['state'=>'Tamil Nadu','country'=>'India'][$key]??'')) ?>" <?= in_array($key,['name','phone'],true)?'required':'' ?> maxlength="<?= $key==='name'?120:20 ?>"></label><?php endforeach; ?>
<p class="o-field-wide b-muted" id="customer-lookup-status" role="status">Enter a phone number to find saved customer details. You can edit all filled details.</p>
<label class="o-field">Order source<select class="o-input" name="channel"><option value="manual" <?= $channel==='manual'?'selected':'' ?>>Manual / phone / walk-in</option><option value="whatsapp" <?= $channel==='whatsapp'?'selected':'' ?>>WhatsApp booking entered by staff</option></select></label><label class="o-field">Payment<select class="o-input" name="payment_mode"><option value="manual">Cash / UPI / bank transfer</option><option value="cod" <?= ($values['payment_mode']??'')==='cod'?'selected':'' ?>>Payment not received — collect on delivery</option></select></label>
<label class="o-field">Delivery area<select class="o-input" id="id_zone" name="zone"><option value="">Collection / takeaway</option><?php foreach($zones as $z): ?><option value="<?= e($z['id']) ?>" <?= (string)($values['zone']??'')===(string)$z['id']?'selected':'' ?>><?= e($z['pincode'].' — '.$z['area_name'].' — ₹'.$z['delivery_fee']) ?></option><?php endforeach; ?></select></label><label class="o-field">Delivery date<input class="o-input" type="date" name="delivery_date" value="<?= e($values['delivery_date']??'') ?>"></label><label class="o-field">Fulfilment<select class="o-input" name="fulfilment_method"><option value="">Use selected local area or collection</option><option value="courier" <?= ($values['fulfilment_method']??'')==='courier'?'selected':'' ?>>Courier outside Chennai — charge after dispatch</option></select></label><?php foreach(['city'=>'City','state'=>'State','country'=>'Country','postal_code'=>'Postal code'] as $key=>$label): ?><label class="o-field"><?= e($label) ?><input class="o-input" name="<?= e($key) ?>" value="<?= e($values[$key]??(['state'=>'Tamil Nadu','country'=>'India'][$key]??'')) ?>" maxlength="100"></label><?php endforeach; ?><label class="o-field o-field-wide">Delivery address<textarea class="o-input" name="address" rows="2" maxlength="2000"><?= e($values['address']??'') ?></textarea></label></div></section>
<section class="o-card b-panel"><div class="b-panel-head"><span class="b-step-number">2</span><div><h2>Order items</h2><p>Browse by meal or search for a dish. Prices appear beside each item.</p></div></div><?php $n=max(1,min(50,(int)($values['lines-TOTAL_FORMS']??1))); ?><input type="hidden" id="id_lines-TOTAL_FORMS" name="lines-TOTAL_FORMS" value="<?= e($n) ?>"><div id="order-lines"><?php for($i=0;$i<$n;$i++)billing_line((string)$i,$catalog,$values); ?></div><button class="o-btn b-add-item" type="button" id="add-line">＋ Add another item</button><p id="line-limit" class="b-muted" role="status"></p></section></div>
<aside class="b-summary"><section class="o-card"><span class="b-eyebrow">Order summary</span><h2>Review your booking</h2><div id="summary-items" class="b-summary-items"></div><dl class="b-totals"><div><dt>Items subtotal</dt><dd id="summary-subtotal">₹0.00</dd></div><div><dt>Delivery</dt><dd id="summary-delivery">₹0.00</dd></div><div class="b-grand-total"><dt>Estimated total</dt><dd id="summary-total">₹0.00</dd></div></dl><p class="b-muted" id="minimum-note"></p><button class="o-btn o-btn-primary b-save">Save order &amp; review total →</button><p class="b-summary-note">Save to review the final total. You can issue an unpaid bill and record collection later.</p></section></aside></form>
<template id="line-template"><?php billing_line('__prefix__',$catalog,[]); ?></template><script id="billing-catalog" type="application/json"><?= json_encode($catalog,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?></script><script id="billing-delivery-areas" type="application/json"><?= json_encode($areas,JSON_HEX_TAG|JSON_THROW_ON_ERROR) ?></script>
<?php $scripts='<script src="'.e(asset_url('billing.js')).'" defer></script><script src="'.e(asset_url('billing-customer.js')).'" defer></script>'; ?>
